static void putu(FILE*f,sda_u128 x){char b[64];sda_print_u128(x,b,sizeof b);fputs(b,f);}static int md(const char*p){return !mkdir(p,0777)||errno==EEXIST?0:-1;}
int sda_epsilon_grid_point(mpfr_t out,mpfr_t lo,mpfr_t hi,unsigned i,unsigned count,sda_epsilon_search_mode mode){if(!count||mpfr_sgn(lo)<=0||mpfr_cmp(lo,hi)>=0||mpfr_cmp_ui(hi,1)>=0||i>=count)return-1;if(count==1){mpfr_add(out,lo,hi,MPFR_RNDN);mpfr_div_ui(out,out,2,MPFR_RNDN);return 0;}mpfr_t t,a;mpfr_inits2(mpfr_get_prec(out),t,a,(mpfr_ptr)0);mpfr_set_ui(t,i,MPFR_RNDN);mpfr_div_ui(t,t,count-1,MPFR_RNDN);if(mode==SDA_EPS_LOG_GRID){mpfr_div(a,hi,lo,MPFR_RNDN);mpfr_pow(a,a,t,MPFR_RNDN);mpfr_mul(out,lo,a,MPFR_RNDN);}else{mpfr_sub(a,hi,lo,MPFR_RNDN);mpfr_mul(a,a,t,MPFR_RNDN);mpfr_add(out,lo,a,MPFR_RNDN);}mpfr_clears(t,a,(mpfr_ptr)0);return 0;}
int sda_expanded_stage_bounds(int k,size_t n,int stage,mpfr_t pl,mpfr_t pu,mpfr_t lo,mpfr_t hi){if(stage<0||stage>2)return-1;sda_epsilon_bounds(k,n,pl,pu);mpfr_set(lo,pl,MPFR_RNDN);mpfr_set(hi,pu,MPFR_RNDN);if(stage){mpfr_div_2ui(lo,lo,(unsigned)stage,MPFR_RNDN);mpfr_mul_2ui(hi,hi,(unsigned)stage,MPFR_RNDN);mpfr_t cap;mpfr_init2(cap,mpfr_get_prec(hi));mpfr_set_d(cap,.95,MPFR_RNDN);if(mpfr_cmp(hi,cap)>0)mpfr_set(hi,cap,MPFR_RNDN);mpfr_clear(cap);}return 0;}
int sda_frozen_equal(size_t n,sda_u128 q,const sda_u128*p,const sda_u128*c,const sda_frozen_reference*f){return f&&n==f->n&&q==f->q&&!memcmp(p,f->p,n*sizeof*p)&&!memcmp(c,f->c,n*sizeof*c);}
static void set128(mpfr_t x,sda_u128 v){mpfr_set_ui_2exp(x,(unsigned long)(v>>64),64,MPFR_RNDN);mpfr_add_ui(x,x,(unsigned long)v,MPFR_RNDN);}
static void frozen_metrics(sda_ranked_candidate*x,const sda_frozen_reference*f,mpfr_prec_t pr){mpfr_t a,b,d,lq,lf;mpfr_inits2(pr,a,b,d,lq,lf,(mpfr_ptr)0);set128(lq,x->q);set128(lf,f->q);mpfr_log2(lq,lq,MPFR_RNDN);mpfr_log2(lf,lf,MPFR_RNDN);mpfr_sub(x->frozen_log2_q,lq,lf,MPFR_RNDN);mpfr_abs(x->frozen_log2_q,x->frozen_log2_q,MPFR_RNDN);mpfr_set_zero(x->frozen_l1,0);mpfr_set_zero(x->frozen_max,0);x->mass_mismatch_count=0;for(size_t i=0;i<x->n;i++){set128(a,x->p[i]);set128(b,f->p[i]);set128(lq,x->q);set128(lf,f->q);mpfr_div(a,a,lq,MPFR_RNDN);mpfr_div(b,b,lf,MPFR_RNDN);mpfr_sub(d,a,b,MPFR_RNDN);mpfr_abs(d,d,MPFR_RNDN);mpfr_add(x->frozen_l1,x->frozen_l1,d,MPFR_RNDN);if(mpfr_cmp(d,x->frozen_max)>0)mpfr_set(x->frozen_max,d,MPFR_RNDN);if(x->p[i]!=f->p[i])x->mass_mismatch_count++;}x->frozen_identical=(unsigned)sda_frozen_equal(x->n,x->q,x->p,x->c,f);mpfr_clears(a,b,d,lq,lf,(mpfr_ptr)0);}
static uint64_t fnv(uint64_t h,const void*p,size_t n){const unsigned char*b=p;while(n--)h=(h^*b++)*1099511628211ULL;return h;}void sda_expanded_basis_hash(char out[17],mpfr_t*a,size_t n,mpfr_t eps,mpfr_prec_t pr){mpfr_t z;mpz_t v;mpfr_init2(z,pr);mpz_init(v);mpfr_ui_div(z,1,eps,MPFR_RNDN);mpfr_pow_ui(z,z,n+1,MPFR_RNDN);mpfr_get_z(v,z,MPFR_RNDU);uint64_t h=fnv(1469598103934665603ULL,&n,sizeof n);h=fnv(h,&pr,sizeof pr);char*b=mpz_get_str(0,16,v);h=fnv(h,b,strlen(b));free(b);for(size_t i=0;i<n;i++){mpfr_mul_z(z,a[i],v,MPFR_RNDN);mpfr_get_z(v,z,MPFR_RNDN);b=mpz_get_str(0,16,v);h=fnv(h,b,strlen(b));free(b);}snprintf(out,17,"%016llx",(unsigned long long)h);mpz_clear(v);mpfr_clear(z);}
static int close_kind;static int closecmp(const void*A,const void*B){const sda_ranked_candidate*a=*(const sda_ranked_candidate*const*)A,*b=*(const sda_ranked_candidate*const*)B;int c=mpfr_cmp(a->frozen_l1,b->frozen_l1);if(!c)c=mpfr_cmp(a->frozen_max,b->frozen_max);if(!c)c=mpfr_cmp(a->frozen_log2_q,b->frozen_log2_q);if(!c)c=(a->first_trial>b->first_trial)-(a->first_trial<b->first_trial);(void)close_kind;return c;}
static int rk;static int rcmp(const void*A,const void*B){const sda_ranked_candidate*a=*(const sda_ranked_candidate*const*)A,*b=*(const sda_ranked_candidate*const*)B;int c=rk==0?mpfr_cmp(a->pointwise,b->pointwise):rk==1?mpfr_cmp(a->sd,b->sd):rk==2?mpfr_cmp(a->rd,b->rd):(a->q>b->q)-(a->q<b->q);if(!c&&a->q!=b->q)c=a->q<b->q?-1:1;if(!c)c=(a->first_trial>b->first_trial)-(a->first_trial<b->first_trial);return c;}static void vec(FILE*f,const char*n,const sda_u128*v,size_t z){fprintf(f,"%s=",n);for(size_t i=0;i<z;i++){if(i)fputc(' ',f);putu(f,v[i]);}fputc('\n',f);}static void ranking(FILE*f,sda_candidate_set*s,const char*name,int kind,unsigned top){sda_ranked_candidate**v=malloc(s->count*sizeof*v);if(!v)return;for(size_t i=0;i<s->count;i++)v[i]=s->items+i;rk=kind;qsort(v,s->count,sizeof*v,rcmp);fprintf(f,"[%s]\n",name);for(size_t i=0;i<s->count&&i<top;i++){sda_ranked_candidate*x=v[i];fprintf(f,"rank=%zu candidate_id=%zu stage=%u epsilon=%s inside_paper_interval=%s q=",i+1,(size_t)(x-s->items)+1,x->first_stage,x->epsilon,x->inside_paper_interval?"true":"false");putu(f,x->q);fprintf(f," pointwise=");mpfr_out_str(f,10,0,x->pointwise,MPFR_RNDN);fprintf(f," SD=");mpfr_out_str(f,10,0,x->sd,MPFR_RNDN);fprintf(f," RD=");mpfr_out_str(f,10,0,x->rd,MPFR_RNDN);fputc('\n',f);vec(f,"p",x->p,x->n);}fputc('\n',f);free(v);}
static int write_outputs(const sda_config*c,const sda_expanded_options*o,const sda_frozen_reference*f,sda_candidate_set*s,mpfr_t pl,mpfr_t pu,mpfr_t slo[3],mpfr_t shi[3],const unsigned req[3],const unsigned done[3],unsigned successes,unsigned valid,unsigned compact,char**hashes,size_t hn,int found,unsigned mstage,unsigned mgrid,const char*meps,int minside,unsigned bkz,unsigned recover,unsigned rows,const char*version){char base[180],dir[210],path[280];snprintf(base,sizeof base,"offline/generated/%s",c->parameter_set);snprintf(dir,sizeof dir,"%s/expanded-search",base);if(md("offline/generated")||md(base)||md(dir))return-1;for(size_t i=0;i<s->count;i++)frozen_metrics(s->items+i,f,c->mpfr_precision);snprintf(path,sizeof path,"%s/all_unique_candidates.csv",dir);FILE*out=fopen(path,"w");if(!out)return-1;fprintf(out,"candidate_id,first_stage,last_stage,first_grid,first_epsilon,inside_paper_interval,occurrence_count,q,pointwise,SD,RD,k_bit_compact,frozen_table_identical,p,cumulative\n");mpfr_t target;mpfr_init2(target,c->mpfr_precision);mpfr_set_ui_2exp(target,1,-c->precision_k,MPFR_RNDN);for(size_t i=0;i<s->count;i++){sda_ranked_candidate*x=s->items+i;fprintf(out,"%zu,%u,%u,%u,%s,%s,%u,",i+1,x->first_stage,x->last_stage,x->first_trial,x->epsilon,x->inside_paper_interval?"true":"false",x->occurrences);putu(out,x->q);fputc(',',out);mpfr_out_str(out,10,0,x->pointwise,MPFR_RNDN);fputc(',',out);mpfr_out_str(out,10,0,x->sd,MPFR_RNDN);fputc(',',out);mpfr_out_str(out,10,0,x->rd,MPFR_RNDN);fprintf(out,",%s,%s,\"",mpfr_cmp(x->pointwise,target)<=0?"true":"false",x->frozen_identical?"true":"false");for(size_t j=0;j<x->n;j++){if(j)fputc(' ',out);putu(out,x->p[j]);}fprintf(out,"\",\"");for(size_t j=0;j<x->n;j++){if(j)fputc(' ',out);putu(out,x->c[j]);}fprintf(out,"\"\n");char cp[280];snprintf(cp,sizeof cp,"%s/candidate_%zu.txt",dir,i+1);FILE*cf=fopen(cp,"w");if(!cf)continue;fprintf(cf,"parameter_set=%s\nq=",c->parameter_set);putu(cf,x->q);fputc('\n',cf);vec(cf,"p",x->p,x->n);vec(cf,"cumulative",x->c,x->n);fclose(cf);}fclose(out);snprintf(path,sizeof path,"%s/candidate_plateaus.csv",dir);out=fopen(path,"w");fprintf(out,"candidate_id,q,epsilon_min_seen,epsilon_max_seen,occurrence_count,contiguous_run_count,first_stage,last_stage,p\n");for(size_t i=0;i<s->count;i++){sda_ranked_candidate*x=s->items+i;fprintf(out,"%zu,",i+1);putu(out,x->q);fputc(',',out);mpfr_out_str(out,10,0,x->epsilon_min,MPFR_RNDN);fputc(',',out);mpfr_out_str(out,10,0,x->epsilon_max,MPFR_RNDN);fprintf(out,",%u,%u,%u,%u,\"",x->occurrences,x->contiguous_run_count,x->first_stage,x->last_stage);for(size_t j=0;j<x->n;j++){if(j)fputc(' ',out);putu(out,x->p[j]);}fprintf(out,"\"\n");}fclose(out);snprintf(path,sizeof path,"%s/basis_hashes.csv",dir);out=fopen(path,"w");fprintf(out,"basis_hash\n");for(size_t i=0;i<hn;i++)fprintf(out,"%s\n",hashes[i]);fclose(out);snprintf(path,sizeof path,"%s/top_candidates.txt",dir);out=fopen(path,"w");ranking(out,s,"pointwise_top",0,o->top_count);ranking(out,s,"sd_top",1,o->top_count);ranking(out,s,!strcmp(c->scheme,"Falcon")?"r509_top":"rd_top",2,o->top_count);ranking(out,s,"smallest_q_top",3,o->top_count);fclose(out);snprintf(path,sizeof path,"%s/closest_to_frozen.txt",dir);out=fopen(path,"w");sda_ranked_candidate**v=malloc(s->count*sizeof*v);for(size_t i=0;i<s->count;i++)v[i]=s->items+i;qsort(v,s->count,sizeof*v,closecmp);for(size_t i=0;i<s->count&&i<10;i++){sda_ranked_candidate*x=v[i];fprintf(out,"rank=%zu candidate_id=%zu stage=%u epsilon=%s inside_paper_interval=%s q=",i+1,(size_t)(x-s->items)+1,x->first_stage,x->epsilon,x->inside_paper_interval?"true":"false");putu(out,x->q);fprintf(out," probability_l1=");mpfr_out_str(out,10,0,x->frozen_l1,MPFR_RNDN);fprintf(out," probability_max=");mpfr_out_str(out,10,0,x->frozen_max,MPFR_RNDN);fprintf(out," log2_q_difference=");mpfr_out_str(out,10,0,x->frozen_log2_q,MPFR_RNDN);fprintf(out," mass_mismatch_count=%u pointwise=",x->mass_mismatch_count);mpfr_out_str(out,10,0,x->pointwise,MPFR_RNDN);fprintf(out," SD=");mpfr_out_str(out,10,0,x->sd,MPFR_RNDN);fprintf(out," RD=");mpfr_out_str(out,10,0,x->rd,MPFR_RNDN);fprintf(out," epsilon_plateau=[");mpfr_out_str(out,10,0,x->epsilon_min,MPFR_RNDN);fputc(',',out);mpfr_out_str(out,10,0,x->epsilon_max,MPFR_RNDN);fprintf(out,"]\n");vec(out,"p",x->p,x->n);}free(v);fclose(out);snprintf(path,sizeof path,"%s/search_summary.txt",dir);out=fopen(path,"w");fprintf(out,"parameter_set=%s\nmaster_seed=%llu\nsolver=%s\npaper_epsilon_lower=",c->parameter_set,(unsigned long long)o->seed,!strcmp(c->scheme,"Falcon")?"heuristic-bkz20":"exact-linf-svp");mpfr_out_str(out,10,0,pl,MPFR_RNDN);fprintf(out,"\npaper_epsilon_upper=");mpfr_out_str(out,10,0,pu,MPFR_RNDN);fputc('\n',out);for(int z=0;z<3;z++){fprintf(out,"stage%d_epsilon_min=",z);mpfr_out_str(out,10,0,slo[z],MPFR_RNDN);fprintf(out,"\nstage%d_epsilon_max=",z);mpfr_out_str(out,10,0,shi[z],MPFR_RNDN);fprintf(out,"\nstage%d_requested_points=%u\nstage%d_completed_points=%u\n",z,req[z],z,done[z]);}fprintf(out,"total_solver_successes=%u\ntotal_structurally_valid=%u\nunique_basis_count=%zu\nunique_candidate_count=%zu\nduplicate_occurrence_count=%u\nk_bit_compact_count=%u\nfrozen_table_found=%s\ninterrupted=false\nnormalization_applied=false\n",successes,valid,hn,s->count,valid-(unsigned)s->count,compact,found?"true":"false");if(found){fprintf(out,"matching_stage=%u\nmatching_grid_index=%u\nmatching_epsilon=%s\nmatching_solver=%s\nmatching_q=",mstage,mgrid,meps,!strcmp(c->scheme,"Falcon")?"heuristic-bkz20":"exact-linf-svp");putu(out,f->q);fprintf(out,"\nmatching_p=");for(size_t i=0;i<f->n;i++){if(i)fputc(32,out);putu(out,f->p[i]);}fprintf(out,"\ninside_paper_interval=%s\n",minside?"true":"false");}if(version)fprintf(out,"fplll_version=%s\nBKZ_block_size=20\ncompleted_bkz_runs=%u\nrecoverable_rows=%u\nstructurally_valid_rows=%u\nbkz_seed_controlled=false\n",version,bkz,recover,rows);fclose(out);mpfr_clear(target);return 0;}
int sda_expanded_search(const char*cfgpath,const sda_expanded_options*o,const sda_frozen_reference*frozen){sda_config c;if(sda_config_load(cfgpath,&c)||!o||!frozen)return 1;size_t n=(size_t)(c.support_max-c.support_min+1);mpfr_t pl,pu,slo[3],shi[3],eps;mpfr_inits2(c.mpfr_precision,pl,pu,eps,(mpfr_ptr)0);for(int i=0;i<3;i++)mpfr_inits2(c.mpfr_precision,slo[i],shi[i],(mpfr_ptr)0);unsigned req[3]={0},done[3]={0};for(int z=0;z<3;z++){sda_expanded_stage_bounds(c.precision_k,n,z,pl,pu,slo[z],shi[z]);req[z]=o->expanded?(unsigned)(!strcmp(c.scheme,"Falcon")?(16u<<z):(256u<<z)):0;}if(!o->expanded){req[0]=o->points;if(!req[0])req[0]=256;if(o->min_text&&mpfr_set_str(slo[0],o->min_text,10,MPFR_RNDN))return 2;if(o->max_text&&mpfr_set_str(shi[0],o->max_text,10,MPFR_RNDN))return 2;if(mpfr_sgn(slo[0])<=0||mpfr_cmp(slo[0],shi[0])>=0||mpfr_cmp_ui(shi[0],1)>=0)return 2;}sda_candidate_set set;sda_candidate_set_init(&set,c.mpfr_precision);mpfr_t alpha[32],tail,gs;for(size_t i=0;i<n;i++)mpfr_init2(alpha[i],c.mpfr_precision);mpfr_inits2(c.mpfr_precision,tail,gs,(mpfr_ptr)0);sda_generate_distribution(&c,alpha,n,tail,gs);char**hashes=0;size_t hn=0,hcap=0;unsigned successes=0,valid=0,compact=0,bkz=0,recover=0,rows=0,seq=0;int found=0,minside=0;unsigned mstage=0,mgrid=0;char meps[192]="";char version[128]="";sda_epsilon_rng rng;sda_epsilon_rng_init(&rng,o->seed);for(int stage=0;stage<(o->expanded?3:1)&&!(found&&o->stop_on_match);stage++){for(unsigned gi=0;gi<req[stage];gi++){if(o->mode==SDA_EPS_RANDOM_GRID)sda_epsilon_random(&rng,slo[stage],shi[stage],eps);else if(sda_epsilon_grid_point(eps,slo[stage],shi[stage],gi,req[stage],o->mode))continue;done[stage]++;char hash[17];sda_expanded_basis_hash(hash,alpha,n,eps,c.mpfr_precision);size_t h;for(h=0;h<hn&&strcmp(hashes[h],hash);h++){}if(h==hn){if(hn==hcap){size_t nc=hcap?hcap*2:64;char**nv=realloc(hashes,nc*sizeof*nv);if(!nv)goto fail;hashes=nv;hcap=nc;}hashes[hn]=malloc(17);if(!hashes[hn])goto fail;memcpy(hashes[hn++],hash,17);}int inside=mpfr_cmp(eps,pl)>=0&&mpfr_cmp(eps,pu)<=0;if(strcmp(c.scheme,"Falcon")){sda_candidate_diagnostic d;sda_candidate_diagnostic_init(&d,c.mpfr_precision);int rc=sda_diagnose_frodo_epsilon(&c,eps,&d);if(d.solver_completed)successes++;if(!rc){sda_u128 cum[32],q=d.q;sda_build_cumulative(d.p,n,cum,&q);size_t id;seq++;int ar=sda_candidate_set_observe(&set,n,q,d.p,cum,seq,(unsigned)stage,gi,eps,inside,d.max_pointwise,d.sd,d.rd,d.quality_flags,hash,&id);if(ar<0){sda_candidate_diagnostic_clear(&d);goto fail;}valid++;mpfr_t target;mpfr_init2(target,c.mpfr_precision);mpfr_set_ui_2exp(target,1,-c.precision_k,MPFR_RNDN);if(ar>0&&mpfr_cmp(d.max_pointwise,target)<=0)compact++;mpfr_clear(target);if(sda_frozen_equal(n,q,d.p,cum,frozen)){found=1;minside=inside;mstage=(unsigned)stage;mgrid=gi;mpfr_snprintf(meps,sizeof meps,"%.160Re",eps);set.items[id].frozen_identical=1;}}sda_candidate_diagnostic_clear(&d);}else{sda_falcon_bkz_result b;int rc=sda_falcon_bkz_solve(alpha,eps,c.mpfr_precision,o->seed+gi+stage*100000u,&b);bkz++;recover+=(unsigned)b.recoverable_row_count;rows+=(unsigned)b.structurally_valid_row_count;if(!rc)successes++;if(b.version[0])snprintf(version,sizeof version,"%s",b.version);for(int ri=0;ri<b.valid_candidate_count;ri++){sda_u128 cum[32],q=b.row_q[ri];sda_build_cumulative(b.row_p[ri],n,cum,&q);sda_metrics m;sda_metrics_init(&m,c.mpfr_precision);sda_compute_metrics(alpha,n,b.row_p[ri],q,509,&m);unsigned flags=0;mpfr_t target;mpfr_init2(target,c.mpfr_precision);mpfr_set_ui_2exp(target,1,-72,MPFR_RNDN);if(mpfr_cmp(m.max_absolute_error,target)>0)flags|=1;mpfr_set_ui_2exp(target,1,-78,MPFR_RNDN);mpfr_add_ui(target,target,1,MPFR_RNDN);if(mpfr_cmp(m.renyi,target)>0)flags|=4;size_t id;seq++;int ar=sda_candidate_set_observe(&set,n,q,b.row_p[ri],cum,seq,(unsigned)stage,gi,eps,inside,m.max_absolute_error,m.sd_support,m.renyi,flags,hash,&id);if(ar<0){mpfr_clear(target);sda_metrics_clear(&m);goto fail;}valid++;if(ar>0){mpfr_set_ui_2exp(target,1,-72,MPFR_RNDN);if(mpfr_cmp(m.max_absolute_error,target)<=0)compact++;}if(sda_frozen_equal(n,q,b.row_p[ri],cum,frozen)){found=1;minside=inside;mstage=(unsigned)stage;mgrid=gi;mpfr_snprintf(meps,sizeof meps,"%.160Re",eps);set.items[id].frozen_identical=1;}mpfr_clear(target);sda_metrics_clear(&m);}}if(found&&o->stop_on_match)break;}}int wr=write_outputs(&c,o,frozen,&set,pl,pu,slo,shi,req,done,successes,valid,compact,hashes,hn,found,mstage,mgrid,meps,minside,bkz,recover,rows,version[0]?version:0);fprintf(stderr,"%s expanded-search completed=%u/%u,%u/%u,%u/%u unique_basis=%zu unique_candidates=%zu frozen=%s\n",c.parameter_set,done[0],req[0],done[1],req[1],done[2],req[2],hn,set.count,found?"true":"false");for(size_t i=0;i<hn;i++)free(hashes[i]);free(hashes);sda_candidate_set_clear(&set);for(size_t i=0;i<n;i++)mpfr_clear(alpha[i]);mpfr_clears(tail,gs,pl,pu,eps,(mpfr_ptr)0);for(int i=0;i<3;i++)mpfr_clears(slo[i],shi[i],(mpfr_ptr)0);return wr?1:0;
fail:for(size_t i=0;i<hn;i++)free(hashes[i]);free(hashes);sda_candidate_set_clear(&set);for(size_t i=0;i<n;i++)mpfr_clear(alpha[i]);mpfr_clears(tail,gs,pl,pu,eps,(mpfr_ptr)0);for(int i=0;i<3;i++)mpfr_clears(slo[i],shi[i],(mpfr_ptr)0);return 1;}
